script:
(function () {
  'use strict';
  // Truck loan with upfit/towing costs, longer terms and an optional business-use share.
  //   Purchase = truck price + upfit, towing package and accessories added to the deal.
  //   Taxable amount = purchase - trade-in value (when the trade-in credit box is ticked), never below 0.
  //   Loan = purchase - rebate - down payment - trade-in + owed on trade-in
  //          (+ sales tax and fees when they are financed).
  //   Payment: M = L x i / (1 - (1 + i)^-n), i = APR / 12, n = months (M = L / n at 0%).
  //   Business share of interest = interest x business-use %; estimated tax saving = that x tax rate.
  //   Business cost basis (Section 179 starting point, only above 50% business use) = purchase x business %.
  // Tax figures (tax year 2026):
  //   Section 179 cap for heavy SUVs (over 6,000 lb up to 14,000 lb GVWR): $32,000 — Rev. Proc. 2025-32 sec. .24.
  //   Section 179 only with more than 50% business use; 6-ft cargo-bed exception — IRS Pub. 946 (2025), ch. 2.
  //   Business share of car-loan interest deductible when self-employed — IRS Pub. 463 (2025), ch. 4.
  //   Personal car-loan interest deduction (2025-2028, up to $10,000, new US-assembled vehicles under
  //   14,000 lb, phase-out above $100,000 / $200,000 MAGI) — IRS newsroom (OBBBA provisions), Schedule 1-A.
  //   These are shown as notes only; the calculator does not compute depreciation.
  // Verified in Node (scratchpad tests/auto5): $45,000 truck + $2,500 upfit, 6% tax with $0 trade = $2,850,
  //   $900 fees, $5,000 down, financed -> loan $46,250.00; at 7.5% for 72 months = $799.67/mo (closed form);
  //   $36,000 at 0% for 72 months = $500.00/mo; final balance exactly 0; 60% business use gives 60% of
  //   the interest; term table rows match the formula; no NaN on blank or negative input.
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var TERMS = [36, 48, 60, 72, 84, 96];

  function el(id) { return document.getElementById(id); }
  function setText(id, text) { el(id).textContent = text; }

  function read(id, blankAsZero) {
    var raw = String(el(id).value).trim();
    if (raw === '') return blankAsZero ? 0 : NaN;
    var v = Number(raw);
    return isFinite(v) ? v : NaN;
  }

  function monthlyPayment(principal, annualRate, months) {
    if (months <= 0 || principal <= 0) return 0;
    var i = annualRate / 12;
    if (i === 0) return principal / months;
    return principal * i / (1 - Math.pow(1 + i, -months));
  }

  function amortize(loan, annualRate, months) {
    var pay = monthlyPayment(loan, annualRate, months);
    var i = annualRate / 12, bal = loan, rows = [], totalInterest = 0;
    for (var m = 1; m <= months && bal > 0.005; m++) {
      var interest = bal * i;
      var principal = Math.min(pay - interest, bal);
      bal -= principal;
      if (bal < 0.005 || m === months) bal = 0;
      totalInterest += interest;
      rows.push({ n: m, interest: interest, principal: principal, balance: bal });
    }
    return { payment: pay, rows: rows, totalInterest: totalInterest };
  }

  function diff(v) {
    if (Math.abs(v) < 0.5) return '—';
    return (v > 0 ? '+' : '−') + money0.format(Math.abs(v));
  }

  function clearResults() {
    ['tkPayment', 'tkLoanAmount', 'tkTotalInterest', 'tkTotalCost', 'tkSalesTax', 'tkUpfront',
     'tkTotalPayments', 'tkBizInterest', 'tkBizFirstYear', 'tkBizSaving', 'tkBizBasis'].forEach(function (id) { setText(id, '–'); });
    ['tkBiz', 'tkSec179', 'tkSec179No', 'tkNegativeEquity'].forEach(function (id) { el(id).hidden = true; });
    el('tkTerms').innerHTML = '';
    el('tkSchedule').innerHTML = '';
  }

  function update() {
    var price = read('tkPrice'), upfit = read('tkUpfit', true), months = read('tkTerm'), rate = read('tkRate'),
        down = read('tkDown', true), rebate = read('tkRebate', true), trade = read('tkTrade', true),
        owed = read('tkOwed', true), taxRate = read('tkTaxRate', true), fees = read('tkFees', true),
        biz = read('tkBizUse', true), bizTax = read('tkBizTax', true),
        financeCosts = el('tkFinanceCosts').checked, tradeCredit = el('tkTradeCredit').checked;
    var error = el('tkError'), msg = '';
    if (isNaN(price) || price <= 0) msg = 'Enter a truck price greater than $0.';
    else if (isNaN(months) || months < 1 || months > 120 || months % 1 !== 0) msg = 'Enter a loan term of 1 to 120 whole months.';
    else if (isNaN(rate) || rate < 0 || rate > 40) msg = 'Enter an interest rate from 0% to 40%.';
    else if ([upfit, down, rebate, trade, owed, taxRate, fees, biz, bizTax].some(function (v) { return isNaN(v) || v < 0; })) msg = 'Amounts and rates cannot be negative.';
    else if (taxRate > 20) msg = 'Enter a sales tax rate of 20% or less.';
    else if (biz > 100) msg = 'Business use cannot be more than 100%.';
    else if (bizTax > 60) msg = 'Enter a tax rate on business income of 60% or less.';
    if (msg) { error.hidden = false; error.textContent = msg; clearResults(); return; }

    var purchase = price + upfit;
    var taxable = Math.max(0, purchase - (tradeCredit ? trade : 0));
    var salesTax = taxable * taxRate / 100;
    var loan = purchase - rebate - down - trade + owed + (financeCosts ? salesTax + fees : 0);
    if (loan <= 0.005) {
      error.hidden = false;
      error.textContent = 'Your down payment, rebate and trade-in cover the full cost, so there is nothing to finance.';
      clearResults();
      return;
    }
    error.hidden = true;
    error.textContent = '';
    var r = amortize(loan, rate / 100, months);
    var upfront = down + (financeCosts ? 0 : salesTax + fees);
    var share = biz / 100;

    setText('tkPayment', money.format(r.payment));
    setText('tkLoanAmount', money.format(loan));
    setText('tkTotalInterest', money.format(r.totalInterest));
    setText('tkTotalCost', money.format(purchase - rebate + salesTax + fees + r.totalInterest));
    setText('tkSalesTax', money.format(salesTax));
    setText('tkUpfront', money.format(upfront));
    setText('tkTotalPayments', money.format(loan + r.totalInterest));
    el('tkNegativeEquity').hidden = !(owed > trade);
    setText('tkNegativeAmount', money.format(Math.max(0, owed - trade)));

    var firstYear = 0;
    r.rows.forEach(function (row) { if (row.n <= 12) firstYear += row.interest; });
    el('tkBiz').hidden = !(share > 0);
    setText('tkBizInterest', money.format(r.totalInterest * share));
    setText('tkBizFirstYear', money.format(firstYear * share));
    setText('tkBizSaving', money.format(r.totalInterest * share * bizTax / 100));
    el('tkSec179').hidden = !(share > 0.5);
    el('tkSec179No').hidden = !(share > 0 && share <= 0.5);
    setText('tkBizBasis', money.format(purchase * share));

    el('tkTerms').innerHTML = TERMS.map(function (t) {
      var pay = monthlyPayment(loan, rate / 100, t), interest = pay * t - loan;
      var mark = t === months ? ' class="font-semibold"' : '';
      return '<tr' + mark + '><td>' + t + ' months</td><td>' + money.format(pay) + '</td><td>' +
        money.format(interest) + '</td><td>' + diff(interest - r.totalInterest) + '</td></tr>';
    }).join('');

    var html = [], p = 0, intr = 0;
    r.rows.forEach(function (row, idx) {
      p += row.principal; intr += row.interest;
      if (row.n % 12 === 0 || idx === r.rows.length - 1) {
        html.push('<tr><td>' + Math.ceil(row.n / 12) + '</td><td>' + money.format(p) + '</td><td>' + money.format(intr) +
          '</td><td>' + money.format(intr * share) + '</td><td>' + money.format(row.balance) + '</td></tr>');
        p = 0; intr = 0;
      }
    });
    el('tkSchedule').innerHTML = html.join('');
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = el('tkForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
